import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, Camara, Textura, Profundidad, Brillo, Paso, seguir, enCamino, Chip, Regla, Ondas, Destello, golpe, sacudida, h, clamp, interpolate, Easing} from './kit';

export const SUBS = {arriba: 230, acento: '#E7FF00'};

// ---- tiempos atados a la voz ----
const BOLS1 = en('bolsillos'), DEBAJO = en('Debajo'), BRAZO = en('brazo'), PLIEGUE = en('pliegue'), BOLSA = en('bolsa'), FONDO = en('fondo');
const ERIZOS = en('Erizos'), ALMEJAS = en('almejas'), CANGREJOS = en('cangrejos'), ASI = en('Así'), BUCEAR = en('bucear'), SUBIR = en('subir'), LIBRES = en('libres');
const PERO = en('Pero'), BOLS_E = en('bolsillo'), RARO = en('raro'), PIEDRA1 = en('piedra'), SUBE = en('Sube'), SUPERF = en('superficie'), FLOTA = en('flota');
const PONE = en('pone'), BARRIGA = en('barriga'), AGARRA = en('Agarra'), ALMEJA = en('almeja'), GOLPEA = en('golpea'), ROMPERLA = en('romperla');
const POCOS = en('Pocos'), HERRAM = en('herramientas'), NUTRIA2 = en('nutria', 2), Y4 = en('Y', 4), ALGUNAS = en('algunas'), CARGAN = en('cargan'), SEMANAS = en('semanas');
const SACAN = en('sacan'), COMER = en('comer'), GUARDAR = en('guardar'), QUIEN = en('quien'), LLAVES = en('llaves'), UNA4 = en('Una', 4), FAVORITA = en('favorita');
const NACIO = en('nació'), DALE = en('Dale'), BOLS2 = en('bolsillos', 2), COSAS = en('cosas');

const LIMA = '#E7FF00', MAR1 = '#1F6F7A', MAR2 = '#7FC8C8', PELO = '#6B4A2E';

const Lienzo: React.FC<{children: React.ReactNode}> = ({children}) => <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>{children}</svg>;

// ---------- piezas dibujadas ----------
// Protagonista: la piedra gris lisa con su vetita blanca
const Piedra: React.FC<{x: number; y: number; sc?: number; brillo?: number; ang?: number}> = ({x, y, sc = 1, brillo = 0, ang = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${ang}) scale(${sc})`}>
    <defs><radialGradient id="pdG" cx="35%" cy="30%" r="80%"><stop offset="0%" stopColor="#C8CDD2" /><stop offset="60%" stopColor="#8A9098" /><stop offset="100%" stopColor="#54595F" /></radialGradient></defs>
    {brillo > 0 && <circle r={110 + 30 * brillo} fill={LIMA} opacity={0.35 * brillo} />}
    <ellipse cx={4} cy={44} rx={70} ry={12} fill="rgba(0,0,0,0.3)" />
    <path d="M -64 4 C -62 -42 -10 -58 38 -48 C 74 -38 80 8 56 34 C 24 54 -50 52 -64 4 Z" fill="url(#pdG)" stroke="#3E4247" strokeWidth={4} />
    <path d="M -50 14 C -20 -12 20 -20 62 -8" stroke="#fff" strokeWidth={9} fill="none" strokeLinecap="round" opacity={0.92} />
    <path d="M -10 -4 C 8 -8 22 -8 34 -12" stroke="#fff" strokeWidth={5} fill="none" strokeLinecap="round" opacity={0.7} />
    <ellipse cx={-26} cy={-26} rx={18} ry={8} fill="#fff" opacity={0.4} transform="rotate(-18 -26 -26)" />
  </g>
);

// Nutria marina flotando de espaldas (vista desde arriba). brazo = ángulo del brazo; bolsa = pliegue abierto 0..1; contorno = línea lima
const Nutria: React.FC<{x: number; y: number; sc?: number; rot?: number; brazo?: number; bolsa?: number; contorno?: number; patas?: number}> = ({x, y, sc = 1, rot = 0, brazo = 0, bolsa = 0, contorno = 0, patas = 0}) => {
  const {s} = useS();
  const resp = 1 + 0.012 * Math.sin(s * 2.4);
  return (
    <g transform={`translate(${x} ${y}) rotate(${rot}) scale(${sc * resp})`}>
      <defs>
        <radialGradient id="nuG" cx="40%" cy="35%" r="75%"><stop offset="0%" stopColor="#A5825A" /><stop offset="60%" stopColor={PELO} /><stop offset="100%" stopColor="#3E2A18" /></radialGradient>
        <radialGradient id="caG" cx="40%" cy="35%" r="75%"><stop offset="0%" stopColor="#EAD9BC" /><stop offset="100%" stopColor="#B89C74" /></radialGradient>
      </defs>
      <path d="M 200 -10 C 300 -30 380 -10 430 20 C 380 40 300 40 200 30 Z" fill="#4A3220" />
      {[-1, 1].map((k) => <ellipse key={k} cx={250} cy={k * 70 + Math.sin(s * 3 + k) * 10 * patas} rx={64} ry={26} fill="#4A3220" transform={`rotate(${k * 16} 250 ${k * 70})`} />)}
      <ellipse cx={0} cy={0} rx={240} ry={100} fill="url(#nuG)" stroke="#2E1E10" strokeWidth={5} />
      {Array.from({length: 14}).map((_, i) => <path key={i} d={`M ${-170 + i * 28} ${-60 + (i % 3) * 40} q 10 12 -2 26`} stroke="#8A6A44" strokeWidth={4} fill="none" opacity={0.55} strokeLinecap="round" />)}
      <ellipse cx={-60} cy={-30} rx={90} ry={26} fill="#fff" opacity={0.12} />
      {/* pliegue de piel bajo el brazo */}
      <g transform="translate(-140 -70)">
        <ellipse cx={0} cy={0} rx={50 + 20 * bolsa} ry={20 + 24 * bolsa} fill="#3A2614" stroke="#241608" strokeWidth={4} transform="rotate(-20)" />
        {contorno > 0 && <ellipse cx={0} cy={0} rx={56 + 22 * bolsa} ry={26 + 26 * bolsa} fill="none" stroke={LIMA} strokeWidth={8} strokeDasharray="14 10" opacity={contorno} transform="rotate(-20)" />}
      </g>
      {/* brazo */}
      <g transform={`translate(-150 -90) rotate(${brazo})`}>
        <rect x={-20} y={-100} width={40} height={110} rx={20} fill={PELO} stroke="#2E1E10" strokeWidth={4} />
        <circle cx={0} cy={-104} r={24} fill="#8A6A44" stroke="#2E1E10" strokeWidth={4} />
      </g>
      <ellipse cx={-140} cy={80} rx={20} ry={44} fill={PELO} stroke="#2E1E10" strokeWidth={4} transform="rotate(-20 -140 80)" />
      {/* cabeza */}
      <circle cx={-290} cy={-6} r={80} fill="url(#nuG)" stroke="#2E1E10" strokeWidth={5} />
      <ellipse cx={-312} cy={4} rx={56} ry={50} fill="url(#caG)" />
      <circle cx={-262} cy={-72} r={20} fill={PELO} stroke="#2E1E10" strokeWidth={4} /><circle cx={-262} cy={62} r={20} fill={PELO} stroke="#2E1E10" strokeWidth={4} />
      <circle cx={-330} cy={-18} r={9} fill="#1A1008" /><circle cx={-330} cy={28} r={9} fill="#1A1008" />
      <circle cx={-333} cy={-21} r={3} fill="#fff" /><circle cx={-333} cy={25} r={3} fill="#fff" />
      <ellipse cx={-360} cy={5} rx={14} ry={11} fill="#2A1A10" />
      {[-1, 1].map((k) => [0, 1].map((j) => <path key={k + '' + j} d={`M -352 ${6 + k * 8} q -50 ${k * 14 + (j ? 12 : -8)} -90 ${k * 22 + j * 8}`} stroke="#EDE3D0" strokeWidth={3} fill="none" opacity={0.85} />))}
    </g>
  );
};

const Presa: React.FC<{tipo: 'erizo' | 'almeja' | 'cangrejo'; x: number; y: number; sc?: number; op?: number; abierta?: number}> = ({tipo, x, y, sc = 1, op = 1, abierta = 0}) => (
  <g transform={`translate(${x} ${y}) scale(${sc})`} opacity={op}>
    {tipo === 'erizo' && <>
      {Array.from({length: 18}).map((_, i) => <line key={i} x1={0} y1={0} x2={Math.cos((i / 18) * Math.PI * 2) * 52} y2={Math.sin((i / 18) * Math.PI * 2) * 52} stroke="#5A2A6A" strokeWidth={5} strokeLinecap="round" />)}
      <circle r={30} fill="#7A3A8A" stroke="#4A1A5A" strokeWidth={4} /><circle cx={-8} cy={-10} r={8} fill="#fff" opacity={0.35} />
    </>}
    {tipo === 'almeja' && <>
      <path d={`M -50 ${abierta * 6} C -50 ${-50 - abierta * 30} 50 ${-50 - abierta * 30} 50 ${abierta * 6} Z`} fill="#D8C0B0" stroke="#8A6A58" strokeWidth={4} transform={`rotate(${-abierta * 24} -50 ${abierta * 6})`} />
      <path d={`M -50 0 C -50 50 50 50 50 0 Z`} fill="#C8AE9C" stroke="#8A6A58" strokeWidth={4} transform={`rotate(${abierta * 24} 50 0)`} />
      {abierta > 0.2 && <ellipse cx={0} cy={4} rx={32} ry={12} fill="#F8EEE6" opacity={abierta} />}
      {[-24, 0, 24].map((dx) => <path key={dx} d={`M ${dx} -4 L ${dx * 0.6} -36`} stroke="#8A6A58" strokeWidth={3} opacity={0.6} />)}
    </>}
    {tipo === 'cangrejo' && <>
      <ellipse rx={46} ry={32} fill="#E8662A" stroke="#8A2E0A" strokeWidth={4} />
      {[-1, 1].map((k) => <g key={k}><path d={`M ${k * 40} -10 C ${k * 80} -30 ${k * 84} -64 ${k * 60} -70`} stroke="#E8662A" strokeWidth={10} fill="none" strokeLinecap="round" /><circle cx={k * 60} cy={-74} r={16} fill="#E8662A" stroke="#8A2E0A" strokeWidth={3} /></g>)}
      <circle cx={-14} cy={-30} r={6} fill="#222" /><circle cx={14} cy={-30} r={6} fill="#222" />
      {[-1, 1].map((k) => [0, 1, 2].map((j) => <line key={k + '' + j} x1={k * 36} y1={6 + j * 8} x2={k * 70} y2={14 + j * 16} stroke="#C84A12" strokeWidth={5} strokeLinecap="round" />))}
    </>}
  </g>
);

const Alga: React.FC<{x: number; y: number; alto?: number; col?: string; fase?: number}> = ({x, y, alto = 500, col = '#6A7A2A', fase = 0}) => {
  const {s} = useS();
  const sw = Math.sin(s * 1.3 + fase) * 40;
  return (
    <g>
      <path d={`M ${x} ${y} C ${x + sw} ${y - alto * 0.35} ${x - sw} ${y - alto * 0.7} ${x + sw * 0.6} ${y - alto}`} stroke={col} strokeWidth={22} fill="none" strokeLinecap="round" />
      {[0.3, 0.5, 0.7, 0.9].map((k, i) => <ellipse key={i} cx={x + sw * (k - 0.2) * (i % 2 ? -1 : 1) * 0.9 + (i % 2 ? 26 : -26)} cy={y - alto * k} rx={34} ry={12} fill={col} opacity={0.9} transform={`rotate(${i % 2 ? 30 : -30} ${x + (i % 2 ? 26 : -26)} ${y - alto * k})`} />)}
    </g>
  );
};

const Burbujas: React.FC<{n?: number; x0?: number; w?: number; y0?: number; alto?: number}> = ({n = 14, x0 = 0, w = 1080, y0 = 1900, alto = 1700}) => {
  const {s} = useS();
  return <>{Array.from({length: n}).map((_, i) => <circle key={i} cx={x0 + h(i) * w + Math.sin(s * 2 + i) * 14} cy={y0 - (((s * (60 + h(i * 3) * 70) + h(i * 7) * alto) % alto))} r={7 + h(i * 5) * 16} fill="rgba(255,255,255,0.18)" stroke="rgba(255,255,255,0.7)" strokeWidth={3} />)}</>;
};

const Mar: React.FC<{base?: string; semilla?: number}> = ({base = 'radial-gradient(circle at 50% 30%, #7FC8C8, #2B8A94 55%, #0F3F4C)', semilla = 3}) => (
  <Textura tipo="celulas" base={base} linea="rgba(220,255,255,0.22)" luz="rgba(255,255,255,0.16)" semilla={semilla} escala={1.4} />
);

// ---------- Sitio 1: superficie, nutria mirando a cámara, almeja que asoma (E1) ----------
const Superficie1: React.FC = () => {
  const {s, lin, spr} = useS();
  const brazo = -20 - 130 * lin(BOLS1 - 0.2, BOLS1 + 0.3, 0, 1, Easing.out(Easing.back(2)));
  const asoma = spr(BOLS1 + 0.1, 11, 170);
  return (
    <AbsoluteFill style={{background: '#0F3F4C'}}>
      <Camara paradas={[{t: 0, x: 500, y: 1050, zoom: 1.0}, {t: BOLS1, x: 440, y: 1000, zoom: 1.35}, {t: PIEL_T, x: 380, y: 980, zoom: 1.7}]}>
        <Mar />
        <Brillo x={540} y={900} r={600} color="rgba(220,255,240,0.35)" />
        <Lienzo>
          {[0, 1, 2].map((i) => <ellipse key={i} cx={560} cy={1060} rx={420 + i * 90 + Math.sin(s * 1.4 + i) * 16} ry={170 + i * 36} fill="none" stroke="#fff" strokeWidth={4} opacity={0.35 - i * 0.08} />)}
          <Nutria x={600} y={1060} sc={1.35} brazo={brazo} bolsa={lin(BOLS1, BOLS1 + 0.4, 0, 0.5)} patas={1} />
          <g transform={`translate(${600 - 140 * 1.35 + 2} ${1060 - 90 * 1.35 - 70 * asoma}) scale(${asoma})`}><Presa tipo="almeja" x={0} y={0} sc={0.8} /></g>
        </Lienzo>
        <Ondas x={420} y={970} t0={BOLS1} color={LIMA} radio={260} />
      </Camara>
    </AbsoluteFill>
  );
};
const PIEL_T = en('piel');

// ---------- Sitio 2: el pliegue se abre como una bolsa (E2) ----------
const Pliegue: React.FC = () => {
  const {s, lin} = useS();
  const abre = lin(PLIEGUE, BOLSA, 0, 1);
  const cont = lin(BOLSA - 0.3, BOLSA + 0.2, 0, 1);
  return (
    <AbsoluteFill style={{background: '#2A1A0C'}}>
      <Camara paradas={[{t: DEBAJO - 0.4, x: 540, y: 960, zoom: 1.0}, {t: BRAZO, x: 520, y: 1000, zoom: 1.25}, {t: BOLSA, x: 540, y: 1040, zoom: 1.55}, {t: FONDO, x: 540, y: 1060, zoom: 1.7}]}>
        <Textura tipo="fibra" base="radial-gradient(circle at 50% 50%, #8A6A44, #5A3E24 65%, #2A1A0C)" linea="rgba(40,24,10,0.55)" luz="rgba(220,180,130,0.2)" semilla={4} />
        <Lienzo>
          {Array.from({length: 40}).map((_, i) => <path key={i} d={`M ${h(i) * 1080} ${h(i * 3) * 1920} q 14 ${20 + h(i) * 20} -4 ${40 + h(i * 2) * 30}`} stroke="#B89060" strokeWidth={5} fill="none" opacity={0.4} strokeLinecap="round" />)}
          {/* brazo arriba y el pliegue de piel colgando como bolsa */}
          <path d="M 120 520 C 300 470 700 480 960 540 L 960 760 C 700 700 300 700 120 760 Z" fill="#6B4A2E" stroke="#3E2A18" strokeWidth={6} />
          <ellipse cx={540} cy={1060} rx={300 + 40 * abre} ry={150 + 190 * abre} fill="#3A2614" stroke="#1E1208" strokeWidth={8} />
          <ellipse cx={540} cy={1000 + 60 * abre} rx={250 + 30 * abre} ry={90 + 140 * abre} fill="#1E1208" />
          <ellipse cx={540} cy={1060} rx={316 + 40 * abre} ry={166 + 190 * abre} fill="none" stroke={LIMA} strokeWidth={14} strokeDasharray="1 1" pathLength={1} opacity={0} />
          <ellipse cx={540} cy={1060} rx={316 + 40 * abre} ry={166 + 190 * abre} fill="none" stroke={LIMA} strokeWidth={14} opacity={cont} strokeDasharray="30 18" strokeLinecap="round" />
          <path d={`M 300 ${920 - 40 * abre} Q 540 ${820 - 80 * abre} 780 ${920 - 40 * abre}`} stroke="#8A6A44" strokeWidth={14} fill="none" strokeLinecap="round" opacity={0.8} />
        </Lienzo>
        <Brillo x={540} y={1060} r={420} color="rgba(231,255,0,0.25)" t0={BOLSA} />
        <Chip texto="bolsillo" x={540} y={470} t0={BOLSA} t1={FONDO} size={78} />
        <Ondas x={540} y={1060} t0={BOLSA} color={LIMA} radio={420} />
      </Camara>
    </AbsoluteFill>
  );
};

// ---------- Sitio 3: fondo marino, presas al bolsillo y subida con las manos libres (E3-E4) ----------
const RUTA_SUBE: [number, number][] = [[800, 1250], [700, 1000], [600, 700], [560, 430]];
const Fondo3: React.FC = () => {
  const {s, lin} = useS();
  const nx = interpolate(s, [FONDO - 0.2, ERIZOS, ALMEJAS, CANGREJOS, ASI + 0.2], [540, 300, 540, 790, 790], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const baja = lin(FONDO - 0.3, ERIZOS - 0.2, 0, 1);
  let ny = 400 + 850 * baja, rot = 70 - 50 * baja;
  const q = enCamino(s, RUTA_SUBE, SUBIR - 0.4, LIBRES + 0.6);
  const sube = s > SUBIR - 0.4;
  const ex = sube ? q.x : nx, ey = sube ? q.y : ny;
  if (sube) rot = -90 + 20 * Math.sin(s * 3);
  const item = (t0: number, x0: number, tipo: 'erizo' | 'almeja' | 'cangrejo') => {
    const k = lin(t0 + 0.15, t0 + 0.6, 0, 1, Easing.in(Easing.quad));
    if (s > t0 + 0.65) return null;
    return <Presa tipo={tipo} x={x0 + (ex - x0) * k} y={1470 + (ey - 1470) * k} sc={1 - 0.8 * k} op={1 - k * 0.2} />;
  };
  const paradas = [{t: FONDO, x: 540, y: 1000, zoom: 1.0}, {t: ERIZOS, x: 400, y: 1330, zoom: 1.5}, {t: CANGREJOS, x: 700, y: 1330, zoom: 1.5}, {t: BUCEAR, x: 640, y: 1250, zoom: 1.1}, ...seguir(RUTA_SUBE, SUBIR - 0.4, LIBRES + 0.6, 1.3, 5)];
  return (
    <AbsoluteFill style={{background: '#0F3F4C'}}>
      <Camara paradas={paradas}>
        <Mar base="linear-gradient(180deg, #7FC8C8 0%, #2B8A94 35%, #0F4A58 75%, #0A2E3A 100%)" semilla={7} />
        <Brillo x={540} y={200} r={600} color="rgba(220,255,240,0.4)" />
        <Lienzo>
          <path d="M -50 1500 C 200 1470 400 1520 640 1490 C 880 1470 1000 1500 1130 1480 L 1130 1960 L -50 1960 Z" fill="#C9AE7A" stroke="#8A6E3C" strokeWidth={5} />
          {[120, 330, 650, 930].map((x, i) => <Alga key={x} x={x} y={1500} alto={600 + (i % 2) * 220} col={['#6A7A2A', '#8A8A32', '#5A6A28', '#7A7A2E'][i]} fase={i} />)}
          {item(ERIZOS, 300, 'erizo')}{item(ALMEJAS, 540, 'almeja')}{item(CANGREJOS, 790, 'cangrejo')}
          {s < ERIZOS - 0.5 || true ? null : null}
          <Presa tipo="erizo" x={300} y={1470} sc={s < ERIZOS + 0.15 ? 1 : 0} />
          <Presa tipo="almeja" x={540} y={1480} sc={s < ALMEJAS + 0.15 ? 1 : 0} />
          <Presa tipo="cangrejo" x={790} y={1465} sc={s < CANGREJOS + 0.15 ? 1 : 0} />
          <Nutria x={ex} y={ey} sc={0.62} rot={rot} brazo={sube ? 30 * Math.sin(s * 8) : 0} patas={1} bolsa={0.3} contorno={lin(ERIZOS, ERIZOS + 0.3, 0, 1) * (1 - lin(BUCEAR, BUCEAR + 0.4, 0, 1))} />
          <Burbujas n={18} />
        </Lienzo>
        {[ERIZOS, ALMEJAS, CANGREJOS].map((t, i) => <Ondas key={i} x={interpolate(s, [t - 0.1, t], [nx, nx], clamp)} y={1340} t0={t + 0.5} color={LIMA} radio={200} />)}
      </Camara>
    </AbsoluteFill>
  );
};

// ---------- Sitio 4: la piedra con la vetita en el fondo (E5) ----------
const FondoPiedra: React.FC = () => {
  const {s, lin} = useS();
  const garra = lin(RARO - 0.4, PIEDRA1 + 0.1, 0, 1, Easing.out(Easing.cubic));
  const br = lin(PIEDRA1, PIEDRA1 + 0.25, 0, 1);
  return (
    <AbsoluteFill style={{background: '#0A2E3A'}}>
      <Camara paradas={[{t: PERO - 0.3, x: 540, y: 1200, zoom: 1.0}, {t: BOLS_E, x: 560, y: 1300, zoom: 1.25}, {t: RARO, x: 560, y: 1380, zoom: 1.5}, {t: PIEDRA1 + 1.5, x: 540, y: 1370, zoom: 1.8}]}>
        <Mar base="linear-gradient(180deg, #2B8A94 0%, #0F4A58 55%, #0A2E3A 100%)" semilla={12} />
        <Brillo x={540} y={1350} r={520} color="rgba(231,255,200,0.3)" />
        <Lienzo>
          <path d="M -50 1480 C 300 1440 700 1500 1130 1450 L 1130 1960 L -50 1960 Z" fill="#B89A66" stroke="#7A5E32" strokeWidth={5} />
          {[80, 240, 860, 1000].map((x, i) => <Alga key={x} x={x} y={1480} alto={900 - i * 90} col={['#6A7A2A', '#8A8A32', '#5A6A28', '#7A7A2E'][i]} fase={i * 2} />)}
          <Piedra x={560} y={1400} sc={1.5} brillo={br} />
          {/* pata de la nutria que se acerca */}
          <g transform={`translate(${-160 + 460 * garra} ${1290 + 40 * garra}) rotate(${-20 + 40 * garra})`}>
            <rect x={-200} y={-30} width={260} height={60} rx={30} fill={PELO} stroke="#2E1E10" strokeWidth={5} />
            <circle cx={64} cy={0} r={38} fill="#8A6A44" stroke="#2E1E10" strokeWidth={5} />
            {[-14, 0, 14].map((dy) => <line key={dy} x1={80} y1={dy} x2={102} y2={dy * 1.2} stroke="#2E1E10" strokeWidth={4} strokeLinecap="round" />)}
          </g>
          <Burbujas n={12} />
        </Lienzo>
        <Ondas x={560} y={1400} t0={PIEDRA1} color={LIMA} radio={420} />
      </Camara>
      <Destello t0={PIEDRA1} fuerza={0.25} />
    </AbsoluteFill>
  );
};

// ---------- Sitio 5: superficie, piedra en la barriga y almeja golpeada (E6-E7) ----------
const Barriga: React.FC = () => {
  const {s, lin, spr} = useS();
  const sube = lin(SUBE, FLOTA, 0, 1, Easing.out(Easing.cubic));
  const pied = lin(PONE, BARRIGA, 0, 1, Easing.inOut(Easing.cubic));
  const golpes = s > GOLPEA - 0.2 && s < ROMPERLA + 0.1;
  const ciclo = ((s - GOLPEA + 0.2) / 0.55) % 1;
  const baja = golpes ? Math.pow(Math.abs(Math.sin(ciclo * Math.PI)), 0.7) : 0;
  const alm = lin(AGARRA, GOLPEA - 0.2, 0, 1);
  const abierta = lin(ROMPERLA, ROMPERLA + 0.4, 0, 1, Easing.out(Easing.cubic));
  const sac = sacudida(s, [GOLPEA + 0.0, GOLPEA + 0.55, GOLPEA + 1.1, GOLPEA + 1.65, GOLPEA + 2.2, ROMPERLA - 0.1], 7);
  const ax = 560, ay = 1000;
